import{_ as t,c as s,o as a,ak as i}from"./chunks/framework.CjUXqSHI.js";const u=JSON.parse('{"title":"Stores","description":"Config stores, state stores and secret stores in PURISTA typescript framework","frontmatter":{"title":"Stores","description":"Config stores, state stores and secret stores in PURISTA typescript framework","order":206000},"headers":[],"relativePath":"handbook/2_building_business-logic/stores/index.md","filePath":"handbook/2_building_business-logic/stores/index.md","lastUpdated":1770405988000}'),r={name:"handbook/2_building_business-logic/stores/index.md"};function o(n,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="stores" tabindex="-1">Stores <a class="header-anchor" href="#stores" aria-label="Permalink to “Stores”">​</a></h1><p>Stores in PURISTA are an abstraction layer.<br> They provide a unified interface for handling configurations, secrets and states, without the need to know the actual implementation or used product. This ensures, that the actual business implementation is decoupled and isolated.</p><p>When considering separation of concerns, PURISTA offers three types of stores. While they share similar APIs, each store type is tailored to address specific use cases.</p><h2 id="config-store" tabindex="-1">Config store <a class="header-anchor" href="#config-store" aria-label="Permalink to “Config store”">​</a></h2><p>The config store serves as a repository for storing and retrieving technical configurations. For instance, you might store the URL of a third-party provider here, allowing commands or subscriptions to access this information when needed, such as in the <a href="./../fetch_based_http_client.html">HttpClient</a>.</p><h2 id="secret-store" tabindex="-1">Secret store <a class="header-anchor" href="#secret-store" aria-label="Permalink to “Secret store”">​</a></h2><p>The secret store is designed to safeguard confidential and private data. For instance, if your HTTP request to a third-party provider requires API keys for authentication and authorization, it&#39;s essential to store your personal API key securely in the secret store.</p><h2 id="state-store" tabindex="-1">State store <a class="header-anchor" href="#state-store" aria-label="Permalink to “State store”">​</a></h2><p>State stores are tasked with managing the business states of your application. In PURISTA, commands and subscriptions are designed to be stateless, operating within a distributed system. If, for example, you require user sessions, you would utilize the state store to store session information.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h2><ul><li>Config store: dynamic non-secret configuration values.</li><li>Secret store: credentials/tokens/certificates.</li><li>State store: domain/application state shared across instances.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to “Common pitfalls”">​</a></h2><ul><li>storing secrets in config store</li><li>coupling business logic to vendor-specific SDKs directly</li><li>expecting store values to be strongly typed without schema validation</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to “Checklist”">​</a></h2><ul><li>correct store type is selected for each data class</li><li>getter/setter/remove capabilities are configured intentionally</li><li>read/write values are validated via schemas where critical</li><li>integration tests cover the concrete provider behavior</li></ul>',15)])])}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
